import os, json, csv, time
import numpy as np

N = 26
R_MIN = 1e-6
SAFETY = 1e-9

P_CENTERS = 'storage/noesis/latest_centers.txt'
P_RADII   = 'storage/noesis/latest_radii.txt'
P_SHADOWS = 'storage/noesis/exports/shadow_prices_tol1e8.csv'
OUT_DIR   = 'storage/noesis/exports'
OUT_JSON  = os.path.join(OUT_DIR, 'operator_gate_sweep_latest.json')

K_LIST   = [15, 20, 25, 30, 40, 60]
TOL_LIST = [1e-9, 5e-9, 1e-8]

def _ensure_dir(p):
    os.makedirs(p, exist_ok=True)

def _load_snapshot():
    try:
        c = np.loadtxt(P_CENTERS, dtype=float).reshape(N, 2)
        r = np.loadtxt(P_RADII, dtype=float).reshape(N,)
        assert c.shape == (N,2) and r.shape == (N,)
        assert np.all(r > 0)
        return c, r
    except Exception:
        # conservative fallback (grid+hole)
        centers = []
        radius = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        c = np.array(centers, dtype=float)
        r = np.full(N, radius, dtype=float)
        return c, r

def _final_shrink(c, r, eps=SAFETY):
    return c, np.maximum(r - eps, R_MIN)

def read_shadow_prices_csv(path):
    rows = []
    if not os.path.exists(path):
        return rows
    with open(path, 'r', newline='') as f:
        reader = csv.DictReader(f)
        hdr = [h.lower() for h in reader.fieldnames]
        def pick(colnames):
            for name in colnames:
                if name in hdr:
                    return hdr.index(name)
            return None
        idx_i  = pick(['i','idx_i','disc_i'])
        idx_j  = pick(['j','idx_j','disc_j'])
        idx_la = pick(['lambda','lambda_est','multiplier','shadow_price'])
        idx_sl = pick(['slack','pair_slack'])
        for row in reader:
            try:
                def at(row, k):
                    if isinstance(k, int):
                        return row[reader.fieldnames[k]]
                    return None
                i  = int(float(at(row, idx_i)))  if idx_i  is not None else None
                j  = int(float(at(row, idx_j)))  if idx_j  is not None else None
                la = float(at(row, idx_la))      if idx_la is not None else None
                sl = float(at(row, idx_sl))      if idx_sl is not None else np.nan
                if i is None or j is None or la is None: continue
                if not (0 <= i < N and 0 <= j < N and i != j): continue
                rows.append({'i': i, 'j': j, 'lambda': la, 'slack': sl})
            except Exception:
                continue
    rows.sort(key=lambda d: d.get('lambda', -np.inf), reverse=True)
    return rows

def boundary_active(c, r, tol):
    x = c[:, 0]; y = c[:, 1]
    return (x - r <= tol) | (1.0 - x - r <= tol) | (y - r <= tol) | (1.0 - y - r <= tol)

# Geometry helpers
def _orient(a, b, c):
    return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])

def _on_segment(a, b, c):
    return (min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and
            min(a[1], b[1]) <= c[1] <= max(a[1], b[1]))

def segments_cross(p1, p2, q1, q2, strict=True):
    o1 = _orient(p1, p2, q1)
    o2 = _orient(p1, p2, q2)
    o3 = _orient(q1, q2, p1)
    o4 = _orient(q1, q2, p2)
    if strict:
        return (o1*o2 < 0) and (o3*o4 < 0)
    if o1 == 0 and _on_segment(p1, p2, q1): return True
    if o2 == 0 and _on_segment(p1, p2, q2): return True
    if o3 == 0 and _on_segment(q1, q2, p1): return True
    if o4 == 0 and _on_segment(q1, q2, p2): return True
    return (o1*o2 < 0) and (o3*o4 < 0)

def detect_crossing_quads(c, r, top_pairs, k, tol):
    act_b = boundary_active(c, r, tol)
    cand = [(d['i'], d['j'], float(d['lambda'])) for d in top_pairs[:k]
            if not (act_b[d['i']] or act_b[d['j']])]
    quads = []
    m = len(cand)
    for a in range(m):
        i, j, la = cand[a]
        pi, pj = c[i], c[j]
        for b in range(a+1, m):
            k_, l, lb = cand[b]
            if len({i, j, k_, l}) < 4:
                continue
            if segments_cross(pi, pj, c[k_], c[l], strict=True):
                score = min(la, lb)  # conservative ranking
                quads.append({'quad': [i, j, k_, l], 'score': score})
    quads.sort(key=lambda q: q['score'], reverse=True)
    return quads

def construct_packing():
    c, r = _load_snapshot()
    c, r = _final_shrink(c, r, eps=SAFETY)

    result = {
        'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
        'settings': [],
        'has_any_candidate': False,
        'best_candidate': None
    }

    top = read_shadow_prices_csv(P_SHADOWS)
    best = None
    for tol in TOL_LIST:
        for k in K_LIST:
            quads = detect_crossing_quads(c, r, top, k, tol)
            entry = {
                'tol': tol,
                'k': k,
                'num_candidates': len(quads),
                'top_candidate': quads[0] if quads else None
            }
            result['settings'].append(entry)
            if quads and (best is None or quads[0]['score'] > best['score']):
                best = {'tol': tol, 'k': k, 'quad': quads[0]['quad'], 'score': quads[0]['score']}
    result['has_any_candidate'] = best is not None
    result['best_candidate'] = best

    _ensure_dir(OUT_DIR)
    try:
        with open(OUT_JSON, 'w') as f:
            json.dump(result, f, indent=2)
    except Exception:
        pass

    return c.astype(float), r.astype(float)
